$rub=static fn(int$c):string=>($c<0?'−':'').number_format(abs($c)/100,2,',',' ').' ₽';$date=static fn(?string$v):string=>$v&&preg_match('/^(\d{4})-(\d{2})-(\d{2})/D',$v,$m)?$m[3].'.'.$m[2].'.'.$m[1]:'Не указан';$states=['missing_norm'=>'Норма не определена','planned'=>'Запланирован','blocked'=>'Заблокирован','ready'=>'Готов к расчёту','no_new_amount'=>'К выплате 0 ₽','completed'=>'Завершён'];
